def flood_fill(grid, start, replacement):
    if not grid:
        return grid
    rows = len(grid)
    cols = len(grid[0])
    r0, c0 = start
    if r0 < 0 or r0 >= rows or c0 < 0 or c0 >= cols:
        return [row[:] for row in grid]
    original = grid[r0][c0]
    if original == replacement:
        return [row[:] for row in grid]
    new_grid = [row[:] for row in grid]
    stack = [(r0, c0)]
    while stack:
        r, c = stack.pop()
        if new_grid[r][c] != original:
            continue
        new_grid[r][c] = replacement
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and new_grid[nr][nc] == original:
                stack.append((nr, nc))
    return new_grid
